WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT CASE WHEN amount >= 3500 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, CASE WHEN session_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_id_tier, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, SIZE(COLLECT_SET(txn_type)) AS num_txn_types_2, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END) AS debit_count, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, COUNT(*) AS cnt, GROUPING(CASE WHEN amount >= 3500 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM sessionized GROUP BY CUBE (CASE WHEN amount >= 3500 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN session_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY amount_tier DESC;
